module std.compiler.nox.digest_gen

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.formula
use std.compiler.nox.flow

#[pure]
fn binary(opcode: Field, left: formula.Value, right: formula.Value) -> formula.Value {
    formula.Value { formula: noun.pair(noun.atom(opcode), noun.pair(left.formula, right.formula)),
        depth: as_u32(as_field(formula.maximum(left.depth, right.depth)) + 2) }
}

// The private subject is [balanced-Digest index]. Both source expressions run
// once, base first; all successful branches only project that materialization.
#[pure]
pub fn read(base: formula.Value, index: formula.Value) -> formula.Value {
    let mut choice = flow.axis(11)
    for turn in 0..3 {
        let i = sub(2, as_field(turn))
        choice = flow.branch(binary(9, flow.axis(3), flow.literal(i)), flow.axis(8 + i), choice)
    }
    let crash = formula.Value { formula: noun.pair(noun.atom(8), flow.literal(0).formula), depth: as_u32(2) }
    let checked = flow.branch(binary(10, flow.axis(3), flow.literal(4)), choice, crash)
    flow.compose(flow.cons(base, index), checked)
}

lib/std/compiler/nox/package_compile.tri.source_text:
module std.compiler.nox.package_compile

use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.job
use std.compiler.nox.module_graph
use std.compiler.nox.module_order
use std.compiler.nox.module_store
use std.compiler.nox.constant_imports
use std.compiler.nox.parser
use std.compiler.nox.module_functions
use std.compiler.nox.module_function_order
use std.compiler.nox.function_plan
use std.compiler.nox.function_gen
use std.compiler.nox.signatures

pub struct Compiled { pub formula: Noun, pub index: U32, pub error: syntax.Error }

#[pure]
fn failed(index: U32, error: syntax.Error) -> Compiled {
    Compiled { formula: noun.atom(0), index, error }
}

#[pure]
pub fn compile(view: job.View) -> Compiled {
    let header = module_graph.entry_header(view)
    if (header.error.code == syntax.ZERO) == false { return failed(view.index, header.error) }
    // No graph storage is needed when the checked header has no direct uses.
    // A one-module package can still contain a self-use and must discover it.
    if syntax.both(header.token.kind == as_u32(13), header.token.value == 7697253) == false {
        let compiled = parser.compile_at(view.source, view.name, header.token.start,
            constant_imports.empty(), view.sequence_limit, view.depth_limit)
        return Compiled { formula: compiled.formula, index: view.index, error: compiled.error }
    }
    let graph = module_graph.discover_open(view, header)
    if (graph.error.code == syntax.ZERO) == false { return failed(graph.error_index, graph.error) }
    let ordered = module_order.sort(graph)
    if (ordered.error.code == syntax.ZERO) == false { return failed(ordered.error_index, ordered.error) }
    let mut bank = module_functions.empty(seq.len(graph.modules))
    for position in 0..4096 {
        if position == seq.len(ordered.modules) {
            if bank.entry == signatures.NONE { return failed(view.index, syntax.error(3, syntax.ZERO, syntax.ZERO)) }
            let sorted = module_function_order.sort(bank.functions, bank.owners,
                graph.names, graph.sources, bank.roots, graph.capacity)
            let plan = function_plan.ordered(bank.functions, bank.bodies, sorted, bank.entry, graph.capacity)
            if (plan.error.code == syntax.ZERO) == false {
                let mut index = view.index
                if plan.error_function < seq.len(bank.owners) {
                    let owner = as_u32(noun.as_field(seq.get(bank.owners, plan.error_function)))
                    index = module_store.read(graph.modules, owner).index
                }
                return failed(index, plan.error)
            }
            let compiled = function_gen.generate(bank.bodies, plan, bank.entry,
                graph.capacity, view.depth_limit, bank.structured)
            return Compiled { formula: compiled.formula, index: view.index, error: compiled.error }
        }
        let owner = as_u32(noun.as_field(seq.get(ordered.modules, position)))
        bank = module_functions.check(graph, owner, view.index, bank)
        if (bank.error.code == syntax.ZERO) == false {
            return failed(module_store.read(graph.modules, owner).index, bank.error)
        }
    }
    failed(view.index, syntax.error(7, syntax.ZERO, syntax.ZERO))
}

lib/std/compiler/nox/headers.tri.source_text:
module std.compiler.nox.headers

use std.compiler.nox.const_parse
use std.compiler.nox.constants
use std.compiler.nox.constant_imports
use std.compiler.nox.attributes
use vm.core.convert
use vm.core.field
use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.symbols
use std.compiler.nox.signatures
use std.compiler.nox.header_state
use std.compiler.nox.types
use std.compiler.nox.struct_parse
use std.compiler.nox.type_parse
use std.compiler.nox.type_imports

#[pure]
fn expected(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    if token.kind == as_u32(46) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(13) { return syntax.error(6, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
pub fn scalar(token: syntax.Token) -> Field { type_parse.scalar(token) }

#[pure]
fn open(source: bytes.Bytes, input: header_state.State, cap: U32) -> header_state.State {
    let mut s = input
    // Called at the closing parameter parenthesis, with an optional annotation.
    s.token = lexer.next(source, s.token.end)
    if s.token.kind == as_u32(9) {
        s.token = lexer.next(source, s.token.end)
        let parsed = type_parse.parse(source, s.token, s.types, cap)
        s.error = parsed.error
        if (s.error.code == syntax.ZERO) == false { return s }
        s.current.returns = parsed.ty
        s.token = parsed.token
    }
    if (s.token.kind == as_u32(7)) == false { s.error = expected(s.token) return s }
    s.current.open = s.token.end
    s.phase = 2
    s.nesting = as_u32(1)
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn parameter(source: bytes.Bytes, input: header_state.State, cap: U32) -> header_state.State {
    let mut s = input
    if s.token.kind == as_u32(6) { return open(source, s, cap) }
    let name = s.token
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(17)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    let parsed = type_parse.parse(source, s.token, s.types, cap)
    s.error = parsed.error
    if (s.error.code == syntax.ZERO) == false { return s }
    if seq.len(s.params) == cap { s.error = syntax.error(7, name.start, name.end) return s }
    s.params = seq.push(s.params, symbols.binding(name, false, parsed.ty), cap)
    s.current.count = syntax.inc(s.current.count)
    s.token = parsed.token
    if s.token.kind == as_u32(6) { return open(source, s, cap) }
    if (s.token.kind == as_u32(26)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn step(source: bytes.Bytes, input: header_state.State, cap: U32, type_limit: U32) -> header_state.State {
    let mut s = input
    if s.phase == 1 { return parameter(source, s, cap) }
    if s.phase == 2 {
        if s.token.kind == syntax.ZERO { s.error = expected(s.token) return s }
        if s.token.kind == as_u32(14) { s.error = ast.failed(s.token, 1) return s }
        if s.token.kind == as_u32(7) { s.nesting = syntax.inc(s.nesting) }
        if s.token.kind == as_u32(8) {
            s.nesting = syntax.dec(s.nesting)
            if s.nesting == syntax.ZERO {
                // Function count is checked before its header/body scan begins.
                // Each sparse table has at most one entry per completed local
                // declaration, so that check also leaves room for these pushes.
                if s.current.name.value == 1835100526 { s.entry = seq.len(s.functions) }
                s.current.close = s.token.end
                if s.current_pure {
                    s.pure_functions = seq.push(s.pure_functions, noun.atom(as_field(seq.len(s.functions))), cap)
                    s.current_pure = false
                }
                if s.current_public {
                    s.public_functions = seq.push(s.public_functions, noun.atom(as_field(seq.len(s.functions))), cap)
                    s.current_public = false
                }
                s.functions = seq.push(s.functions, signatures.pack(s.current), cap)
                s.phase = 0
            }
        }
        s.token = lexer.next(source, s.token.end)
        return s
    }
    if s.token.kind == syntax.ZERO { s.done = true return s }
    let annotated = s.token.kind == attributes.HASH
    if annotated {
        let parsed = attributes.parse(source, s.token)
        s.token = parsed.token
        s.error = parsed.error
        if (s.error.code == syntax.ZERO) == false { return s }
        if parsed.pure { s.current_pure = true }
    }
    let mut public = false
    if s.token.kind == as_u32(40) { public = true s.token = lexer.next(source, s.token.end) }
    if annotated {
        if (s.token.kind == as_u32(11)) == false {
            if s.token.kind == as_u32(14) { s.error = syntax.error(1, s.token.start, s.token.end) }
            else { s.error = syntax.error(2, s.token.start, s.token.end) }
            return s
        }
    }
    if s.token.kind == as_u32(45) {
        s.constants.owner = s.types.owner
        let parsed = const_parse.parse(source, s.token, s.constants, public, cap)
        s.constants = parsed.scope
        s.token = parsed.token
        s.error = parsed.error
        return s
    }
    if s.token.kind == as_u32(39) {
        if seq.len(s.types.records) == type_limit { s.error = ast.failed(lexer.next(source, s.token.end), 7) return s }
        let parsed = struct_parse.parse(source, s.token, s.types, public, cap)
        s.types = parsed.scope
        s.token = parsed.token
        s.error = parsed.error
        return s
    }
    if (s.token.kind == as_u32(11)) == false { s.error = expected(s.token) return s }
    if seq.len(s.functions) == cap { s.error = syntax.error(7, s.token.start, s.token.end) return s }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(5)) == false { s.error = expected(s.token) return s }
    s.current = signatures.Function { name, params: seq.len(s.params), count: syntax.ZERO, returns: noun.atom(types.UNIT), open: syntax.ZERO, close: syntax.ZERO }
    s.current_public = public
    s.phase = 1
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn chunk(source: bytes.Bytes, input: header_state.State, cap: U32, type_limit: U32) -> header_state.State {
    let mut s = input
    for turn in 0..16 {
        s = step(source, s, cap, type_limit)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Braces are tokens; braces inside comments never delimit bodies.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.SOURCE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, start: U32, owner: bytes.Bytes, cap: U32) -> header_state.State {
    parse_imports(source, start, owner, constant_imports.empty(), cap)
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.SOURCE_CAP < cap) == false)]
pub fn parse_imports(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View, cap: U32) -> header_state.State {
    validate_entry(scan_module(source, start, owner, imports, type_imports.empty(), syntax.ZERO, seq.empty(), seq.empty(), cap))
}

// Shared tables retain prior owners' declarations. This scan records only the
// current owner's entry/purity/visibility and resolves all of its constants.
// Dependency Unit returns use the ordinary omitted return annotation.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.SOURCE_CAP < cap) == false)]
#[requires((cap < seq.len(functions)) == false)]
#[requires((cap < seq.len(params)) == false)]
#[requires((cap < type_start) == false)]
#[ensures((cap < seq.len(result.functions)) == false)]
#[ensures((cap < seq.len(result.params)) == false)]
#[ensures((cap < seq.len(result.public_functions)) == false)]
pub fn scan_module(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View,
    imported_types: type_imports.View, type_start: U32, functions: seq.Seq, params: seq.Seq, cap: U32) -> header_state.State {
    let mut s = header_state.initial(lexer.next(source, start))
    s.functions = functions
    s.params = params
    s.types.owner = owner
    s.types.imports = imported_types
    assert((cap < type_start) == false)
    let type_limit = as_u32(field.sub(as_field(cap), as_field(type_start)))
    s.constants.imports = imports
    for turn in 0..512 {
        s = chunk(source, s, cap, type_limit)
        if (s.error.code == syntax.ZERO) == false { return s }
        if s.done {
            let resolved = constants.resolve(source, s.constants)
            s.constants = resolved.scope
            s.error = resolved.error
            return s
        }
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

// The entry check runs after a successful module scan, never for dependencies.
#[pure]
#[requires(syntax.either(input.entry == signatures.NONE, input.entry < seq.len(input.functions)))]
#[ensures(seq.len(result.functions) == seq.len(input.functions))]
#[ensures(seq.len(result.params) == seq.len(input.params))]
pub fn validate_entry(input: header_state.State) -> header_state.State {
    let mut s = input
    if (s.error.code == syntax.ZERO) == false { return s }
    if s.entry == signatures.NONE { s.error = syntax.error(3, s.token.start, s.token.end) return s }
    let entry = signatures.read(seq.get(s.functions, s.entry))
    if syntax.both(entry.count == syntax.ZERO, noun.eq(entry.returns, noun.atom(types.FIELD))) { return s }
    if syntax.both(entry.count == as_u32(1), noun.eq(entry.returns, noun.atom(types.NOUN))) {
        let parameter = seq.get(s.params, entry.params)
        if noun.eq(noun.tail(noun.tail(parameter)), noun.atom(types.NOUN)) { s.structured = true return s }
    }
    s.error = syntax.error(3, entry.name.start, entry.name.end)
    s
}

lib/std/compiler/nox/type_exports.tri.source_text:
module std.compiler.nox.type_exports

use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.nominal
use std.compiler.nox.types

// The driver publishes final public descriptors built by nominal.build. Their
// owned names and layouts retain defining identity independently of graph IDs.
pub struct Bank { records: seq.Seq, heads: Noun, modules: U32 }
pub struct Found { pub exists: Bool, pub ty: Noun }

#[pure]
#[requires((syntax.SOURCE_CAP < modules) == false)]
#[ensures(len(result) == syntax.ZERO)]
pub fn empty(modules: U32) -> Bank {
    assert((syntax.SOURCE_CAP < modules) == false)
    Bank { records: seq.empty(), heads: tree.empty(tree.shape(modules).height), modules }
}

#[pure]
pub fn len(bank: Bank) -> U32 { seq.len(bank.records) }

// A row is [previous descriptor]; module heads contain row ID+1, or zero.
// Capacity is checked before append. Known descriptors enter unchanged; this
// compiler-owned bank has no serialized-handle admission or source-name spans.
#[pure]
#[requires(len(bank) < cap)]
#[requires((syntax.SOURCE_CAP < cap) == false)]
#[requires(owner < bank.modules)]
#[requires(noun.as_field(noun.head(ty)) == types.NOMINAL)]
#[ensures(as_field(len(result)) == as_field(len(bank)) + 1)]
pub fn push(bank: Bank, owner: U32, ty: Noun, cap: U32) -> Bank {
    assert((syntax.SOURCE_CAP < cap) == false)
    assert(len(bank) < cap)
    assert(owner < bank.modules)
    assert_eq(noun.as_field(noun.head(ty)), types.NOMINAL)
    let id = len(bank)
    let next = tree.get(bank.heads, bank.modules, owner)
    Bank { records: seq.push(bank.records, noun.pair(next, ty), cap),
        heads: tree.set(bank.heads, bank.modules, owner, noun.atom(as_field(id) + 1)), modules: bank.modules }
}

#[pure]
#[requires(owner < bank.modules)]
#[requires((syntax.SOURCE_CAP < bytes.len(name)) == false)]
pub fn find(bank: Bank, owner: U32, name: bytes.Bytes) -> Found {
    let wanted = bytes.to_noun(name)
    let mut cursor = as_u32(noun.as_field(tree.get(bank.heads, bank.modules, owner)))
    for step in 0..4096 {
        if cursor == syntax.ZERO { return Found { exists: false, ty: noun.atom(types.INVALID) } }
        let row = seq.get(bank.records, syntax.dec(cursor))
        let ty = noun.tail(row)
        if noun.eq(nominal.name(ty), wanted) { return Found { exists: true, ty } }
        cursor = as_u32(noun.as_field(noun.head(row)))
    }
    assert(cursor == syntax.ZERO)
    Found { exists: false, ty: noun.atom(types.INVALID) }
}

lib/std/compiler/nox/tuple_bind.tri.source_text:
module std.compiler.nox.tuple_bind

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.symbols
use std.compiler.nox.blocks
use std.compiler.nox.body_state
use std.compiler.nox.tuple_pattern

// The expression has already been parsed against the old scope. Every target
// is checked before a hidden RHS slot or any ordered component writes exist.
#[pure]
pub fn bind(source: bytes.Bytes, input: body_state.State, names: seq.Seq, writable: Bool, declaration: Bool, value: U32, cap: U32) -> body_state.State {
    let mut s = input
    let rhs = seq.get(s.nodes, value)
    let parts = types.parts(ast.ty(rhs))
    let count = seq.len(names)
    if syntax.either(parts.valid == false, (count == parts.count) == false) {
        s.error = ast.issue(5, rhs) return s
    }
    let mut targets = seq.empty()
    for i in 0..16 {
        if i < count {
            let name = tuple_pattern.name(seq.get(names, i))
            if declaration == false {
                let found = symbols.lookup(source, name, s.bindings, s.visible)
                if syntax.either(syntax.either(found.exists == false, found.writable == false), noun.eq(found.ty, types.component(parts, i)) == false) {
                    s.error = syntax.error(5, name.start, name.end) return s
                }
                targets = seq.push(targets, noun.atom(as_field(found.slot)), cap)
            }
        }
    }
    if syntax.either(seq.len(s.bindings) == cap, seq.len(s.nodes) == cap) { s.error = ast.issue(7, rhs) return s }
    let hidden = seq.len(s.bindings)
    let name = syntax.token(1, ast.start(rhs), ast.end(rhs), 0)
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, ast.ty(rhs)), cap)
    s = body_state.append(s, blocks.statement(blocks.WRITE, hidden, value, syntax.ZERO), cap)
    if (s.error.code == syntax.ZERO) == false { return s }
    let base = seq.len(s.nodes)
    s.nodes = seq.push(s.nodes, ast.typed(ast.LOCAL, as_field(hidden), 0, ast.ty(rhs), ast.start(rhs), ast.end(rhs)), cap)
    let mut axis: Field = 2
    for i in 0..16 {
        if i == count { return s }
        let name = tuple_pattern.name(seq.get(names, i))
        if tuple_pattern.discard(name) == false {
            let ty = types.component(parts, i)
            if syntax.either(seq.len(s.nodes) == cap, syntax.both(declaration, seq.len(s.bindings) == cap)) { s.error = ast.issue(7, rhs) return s }
            let mut slot = seq.len(s.bindings)
            if declaration == false { slot = as_u32(noun.as_field(seq.get(targets, i))) }
            let mut projection = axis
            if parts.digest { projection = 4 + as_field(i) }
            let projected = seq.len(s.nodes)
            s.nodes = seq.push(s.nodes, ast.typed(ast.PROJECT, as_field(base), projection, ty, name.start, name.end), cap)
            s = body_state.append(s, blocks.statement(blocks.WRITE, slot, projected, syntax.ZERO), cap)
            if (s.error.code == syntax.ZERO) == false { return s }
            if declaration {
                s.bindings = seq.push(s.bindings, symbols.binding(name, writable, ty), cap)
                s.visible = noun.pair(noun.atom(as_field(slot)), s.visible)
            }
        }
        axis = axis * 2 + 2
    }
    s
}

lib/std/compiler/nox/syntax.tri.source_text:
module std.compiler.nox.syntax

use vm.core.convert
use vm.core.field

pub const ZERO: U32 = 0
pub const SOURCE_CAP: U32 = 4096
pub const STACK_CAP: U32 = 64

// Internal compiler records are shared explicitly between native stages.
pub struct Error { pub code: U32, pub start: U32, pub end: U32 }
pub struct Token { pub kind: U32, pub start: U32, pub end: U32, pub value: Field }

#[pure]
#[requires(value < SOURCE_CAP)]
pub fn inc(value: U32) -> U32 { convert.as_u32(convert.as_field(value) + 1) }

#[pure]
#[requires((value == ZERO) == false)]
pub fn dec(value: U32) -> U32 { convert.as_u32(field.sub(convert.as_field(value), 1)) }

#[pure]
pub fn error(code: Field, start: U32, end: U32) -> Error {
    Error { code: convert.as_u32(code), start, end }
}

#[pure]
pub fn token(kind: Field, start: U32, end: U32, value: Field) -> Token {
    Token { kind: convert.as_u32(kind), start, end, value }
}

// Arguments are evaluated before these Boolean combinators are called.
#[pure]
pub fn either(a: Bool, b: Bool) -> Bool { if a { return true } b }

#[pure]
pub fn both(a: Bool, b: Bool) -> Bool { if a { return b } false }

