module std.compiler.nox.expression

use std.compiler.nox.constants
use std.compiler.nox.qualified_name
use std.compiler.nox.qualified_call
use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.ascii
use std.compiler.nox.symbols
use std.compiler.nox.expression_state
use std.compiler.nox.call_parse
use std.compiler.nox.types
use std.compiler.nox.index_parse
use std.compiler.nox.record_parse
use std.compiler.nox.group_parse
use std.compiler.nox.array_parse

#[pure]
fn operator(s: expression_state.State) -> U32 {
    as_u32(noun.as_field(seq.get(s.operators, syntax.dec(s.ops))))
}

#[pure]
fn precedence(kind: U32) -> U32 {
    if kind == as_u32(30) { return as_u32(5) }
    if kind == as_u32(4) { return as_u32(4) }
    if kind == as_u32(3) { return as_u32(3) }
    if kind == as_u32(29) { return as_u32(2) }
    if kind == as_u32(19) { return as_u32(1) }
    syntax.ZERO
}

#[pure]
fn reduce(input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.vals < as_u32(2) {
        s.error = ast.failed(s.token, 2)
        return s
    }
    let right = seq.get(s.values, syntax.dec(s.vals))
    let left = seq.get(s.values, syntax.dec(syntax.dec(s.vals)))
    if seq.len(s.nodes) == s.node_cap {
        s.error = syntax.error(7, s.token.start, s.token.end)
        return s
    }
    let lhs = seq.get(s.nodes, as_u32(noun.as_field(left)))
    let rhs = seq.get(s.nodes, as_u32(noun.as_field(right)))
    let op = operator(s)
    let mut kind = ast.ADD
    let mut ty = noun.atom(types.FIELD)
    if op == as_u32(4) { kind = ast.MUL }
    if op == as_u32(19) { kind = ast.EQUAL ty = noun.atom(types.BOOL) }
    let mut required = types.FIELD
    if op == as_u32(29) { kind = ast.LESS ty = noun.atom(types.BOOL) required = types.UINT32 }
    if op == as_u32(30) { kind = ast.BIT_AND ty = noun.atom(types.UINT32) required = types.UINT32 }
    if syntax.either((noun.eq(ast.ty(lhs), ast.ty(rhs))) == false,
        syntax.both((kind == ast.EQUAL) == false, (noun.eq(ast.ty(lhs), noun.atom(required))) == false)) {
        s.error = syntax.error(5, ast.start(lhs), ast.end(rhs))
        return s
    }
    if kind == ast.EQUAL {
        if types.contains_noun(ast.ty(lhs)) {
            s.error = syntax.error(5, ast.start(lhs), ast.end(rhs))
            return s
        }
    }
    let id = noun.atom(as_field(seq.len(s.nodes)))
    let node = ast.typed(kind, noun.as_field(left), noun.as_field(right), ty, ast.start(lhs), ast.end(rhs))
    s.nodes = seq.push(s.nodes, node, s.node_cap)
    s.vals = syntax.dec(s.vals)
    s.values = seq.set(s.values, syntax.dec(s.vals), id)
    s.ops = syntax.dec(s.ops)
    s
}

#[pure]
fn push_operator(input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity {
        s.error = syntax.error(7, s.token.start, s.token.end)
        return s
    }
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(s.token.kind)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s
}

#[pure]
fn boundary(kind: U32, before_block: Bool) -> Bool {
    if syntax.either(kind == as_u32(31), kind == as_u32(18)) { return true }
    if syntax.either(syntax.either(kind == as_u32(8), kind == as_u32(15)), kind == as_u32(1)) { return true }
    if syntax.either(syntax.either(kind == as_u32(2), kind == as_u32(5)), kind == as_u32(25)) { return true }
    if syntax.either(syntax.either(kind == as_u32(21), kind == as_u32(22)), kind == as_u32(23)) { return true }
    syntax.both(before_block, kind == as_u32(7))
}

#[pure]
fn step(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let kind = s.token.kind
    if syntax.both(kind == as_u32(8), noun.eq(s.frames, noun.atom(0)) == false) {
        let top = operator(s)
        if top == expression_state.RECORD_MARKER { return record_parse.finish(source, s, true) }
        if top == expression_state.ARRAY_MARKER { s.error = ast.failed(s.token, 2) return s }
        if syntax.either(top == as_u32(36), syntax.either(top == expression_state.TUPLE_MARKER, syntax.either(top == as_u32(5), top == expression_state.CALL_MARKER))) { s.error = ast.failed(s.token, 2) return s }
        if s.operand { s.error = ast.failed(s.token, 2) return s }
        return reduce(s)
    }
    if kind == as_u32(37) {
        if s.ops == syntax.ZERO { s.error = ast.failed(s.token, 2) return s }
        let top = operator(s)
        if top == expression_state.ARRAY_MARKER { return array_parse.finish(source, s, true) }
        if s.operand { s.error = ast.failed(s.token, 2) return s }
        if top == as_u32(36) { return index_parse.finish(source, s) }
        if top == expression_state.RECORD_MARKER { s.error = ast.failed(s.token, 2) return s }
        if syntax.either(top == expression_state.TUPLE_MARKER, syntax.either(top == as_u32(5), top == expression_state.CALL_MARKER)) { s.error = ast.failed(s.token, 2) return s }
        return reduce(s)
    }
    if syntax.either(kind == as_u32(6), kind == as_u32(26)) {
        if s.ops == syntax.ZERO { s.error = ast.failed(s.token, 2) return s }
        let top = operator(s)
        if top == expression_state.ARRAY_MARKER {
            if kind == as_u32(26) { return array_parse.finish(source, s, false) }
            s.error = ast.failed(s.token, 2) return s
        }
        if top == expression_state.RECORD_MARKER {
            if kind == as_u32(26) { return record_parse.finish(source, s, false) }
            s.error = ast.failed(s.token, 2) return s
        }
        if top == as_u32(36) { s.error = ast.failed(s.token, 2) return s }
        if top == expression_state.CALL_MARKER { return call_parse.finish(source, s, kind == as_u32(6)) }
        if top == expression_state.TUPLE_MARKER { return group_parse.finish(source, s, kind == as_u32(6), true) }
        if top == as_u32(5) {
            if kind == as_u32(6) {
                let base = noun.as_field(noun.tail(noun.head(s.frames)))
                if syntax.either(s.operand, (as_field(s.vals) == base + 1) == false) { s.error = ast.failed(s.token, 2) return s }
                // A plain group preserves its child and needs no tuple parser state.
                s.ops = syntax.dec(s.ops)
                s.frames = noun.tail(s.frames)
                s.token = lexer.next(source, s.token.end)
                return s
            }
            return group_parse.finish(source, s, false, false)
        }
        if s.operand == false { return reduce(s) }

        s.error = ast.failed(s.token, 2)
        return s
    }
    if s.operand {
        if syntax.either(syntax.either(kind == as_u32(2), kind == as_u32(1)), syntax.either(kind == as_u32(21), kind == as_u32(22))) {
            if syntax.either(s.vals == s.capacity, seq.len(s.nodes) == s.node_cap) {
                s.error = syntax.error(7, s.token.start, s.token.end)
                return s
            }
            let mut node = ast.typed(ast.LITERAL, s.token.value, 0, noun.atom(types.FIELD), s.token.start, s.token.end)
            if syntax.either(kind == as_u32(21), kind == as_u32(22)) {
                let mut value: Field = 0
                if kind == as_u32(22) { value = 1 }
                node = ast.typed(ast.BOOLEAN, value, 0, noun.atom(types.BOOL), s.token.start, s.token.end)
            }
            if kind == as_u32(1) {
                let following = lexer.next(source, s.token.end)
                if following.kind == as_u32(7) {
                    if record_parse.starts(source, s.token, following, s.before_block, s.frames) { return record_parse.enter(source, following, s) }
                }
                if following.kind == as_u32(5) {
                    if ascii.same_line(source, s.token.end, following.start) {
                        return call_parse.enter(source, following, s)
                    }
                }
                let binding = symbols.lookup(source, s.token, s.context.bindings, s.context.visible)
                if following.kind == as_u32(41) {
                    if binding.exists {
                        if qualified_call.follows(source, following, s.before_block, s.frames) {
                            let name = qualified_name.parse(source, s.token)
                            s.error = name.error
                            if (s.error.code == syntax.ZERO) == false { return s }
                            if name.token.kind == as_u32(7) { return record_parse.enter_qualified(source, name, s) }
                            return call_parse.enter_qualified(source, name, s)
                        }
                    }
                }
                if syntax.both(following.kind == as_u32(41), binding.exists == false) {
                    let name = qualified_name.parse(source, s.token)
                    s.error = name.error
                    if (s.error.code == syntax.ZERO) == false { return s }
                    if name.token.kind == as_u32(5) {
                        if ascii.same_line(source, name.end, name.token.start) {
                            return call_parse.enter_qualified(source, name, s)
                        }
                    }
                    if name.token.kind == as_u32(7) {
                        if record_parse.starts(source, name.member, name.token, s.before_block, s.frames) {
                            return record_parse.enter_qualified(source, name, s)
                        }
                    }
                    let value = constants.imported(source, name, s.context.scope.constants)
                    if value.exists == false { s.error = syntax.error(5, name.start, name.end) return s }
                    node = ast.typed(ast.CONSTANT, value.value, 0, value.ty, name.start, name.end)
                    s.token = name.token
                } else if binding.exists {
                    node = ast.typed(ast.LOCAL, as_field(binding.slot), 0, binding.ty, s.token.start, s.token.end)
                    s.token = following
                } else {
                    let value = constants.lookup(source, s.token, s.context.scope.constants)
                    if value.exists == false { s.error = syntax.error(5, s.token.start, s.token.end) return s }
                    node = ast.typed(ast.CONSTANT, value.value, 0, value.ty, s.token.start, s.token.end)
                    s.token = following
                }
            }
            let id = noun.atom(as_field(seq.len(s.nodes)))
            s.nodes = seq.push(s.nodes, node, s.node_cap)
            s.values = ast.store(s.values, s.vals, id, s.capacity)
            s.vals = syntax.inc(s.vals)
            s.operand = false
            if kind == as_u32(1) { return s }
        } else if kind == as_u32(5) {
            s = push_operator(s)
            if s.error.code == syntax.ZERO {
                let position = noun.pair(noun.atom(as_field(s.token.start)), noun.atom(as_field(s.vals)))
                s.frames = noun.pair(position, s.frames)
            }
        }
        else if kind == as_u32(36) { return array_parse.enter(source, s) }
        else {
            s.error = ast.failed(s.token, 2)
            return s
        }
    } else if kind == as_u32(41) { return record_parse.project(source, s) }
    else if kind == as_u32(36) { return index_parse.enter(source, s) }
    else if syntax.ZERO < precedence(kind) {
        if (s.ops == syntax.ZERO) == false {
            let top = operator(s)
            if syntax.both((top == as_u32(5)) == false, (precedence(top) < precedence(kind)) == false) { return reduce(s) }
        }
        s = push_operator(s)
        s.operand = true
    } else if boundary(kind, s.before_block) {
        if (s.ops == syntax.ZERO) == false {
            let top = operator(s)
            if top == expression_state.ARRAY_MARKER { s.error = ast.failed(s.token, 2) return s }
            if syntax.either(top == expression_state.RECORD_MARKER, syntax.either(top == as_u32(36), syntax.either(top == expression_state.TUPLE_MARKER, syntax.either(top == as_u32(5), top == expression_state.CALL_MARKER)))) {
                s.error = ast.failed(s.token, 2)
                return s
            }
            return reduce(s)
        }
        s.done = true
        return s
    } else {
        s.error = ast.failed(s.token, 2)
        return s
    }
    if s.error.code == syntax.ZERO { s.token = lexer.next(source, s.token.end) }
    s
}

#[pure]
fn chunk(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    for turn in 0..32 {
        s = step(source, s)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn parse(source: bytes.Bytes, token: syntax.Token, context: expression_state.Context, nodes: seq.Seq, arguments: seq.Seq, edges: Noun, cap: U32, before_block: Bool) -> expression_state.Parsed {
    let zero = syntax.ZERO
    let mut capacity = cap
    if syntax.STACK_CAP < capacity { capacity = syntax.STACK_CAP }
    let mut s = expression_state.State { operators: seq.empty(), values: seq.empty(), ops: zero, vals: zero,
        token, operand: true, done: false, error: syntax.error(0, zero, zero),
        capacity, node_cap: cap, nodes, context, before_block, arguments, edges, needs_get: false, frames: noun.atom(0) }
    for block in 0..256 {
        s = chunk(source, s)
        if (s.error.code == zero) == false { return expression_state.Parsed { needs_get: s.needs_get, nodes: s.nodes, arguments: s.arguments, edges: s.edges, value: zero, token: s.token, error: s.error } }
        if s.done {
            assert_eq(as_field(s.vals), 1)
            return expression_state.Parsed { needs_get: s.needs_get, nodes: s.nodes, arguments: s.arguments, edges: s.edges, value: as_u32(noun.as_field(seq.get(s.values, zero))), token: s.token, error: s.error }
        }
    }
    expression_state.Parsed { needs_get: s.needs_get, nodes: s.nodes, arguments: s.arguments, edges: s.edges, value: zero, token: s.token, error: syntax.error(7, s.token.start, s.token.end) }
}

lib/std/compiler/nox/utf8.tri.source_text:
module std.compiler.nox.utf8

use std.nox.bytes
use std.compiler.nox.syntax
use vm.core.convert

struct Scan { pos: U32, pending: U32, lead: U32, low: U32, high: U32, error: Bool }

#[pure]
fn chunk(source: bytes.Bytes, input: Scan) -> Scan {
    let mut s = input
    for step in 0..64 {
        if s.pos == bytes.len(source) { return s }
        let c = bytes.get(source, s.pos)
        if (s.pending == syntax.ZERO) == false {
            if syntax.either(c < s.low, (c < s.high) == false) {
                s.error = true
                s.pos = syntax.inc(s.pos)
                return s
            }
            s.pending = syntax.dec(s.pending)
            s.low = as_u32(128)
            s.high = as_u32(192)
        } else {
            if (c < as_u32(128)) == false {
                s.lead = s.pos
                s.low = as_u32(128)
                s.high = as_u32(192)
                if syntax.either(c < as_u32(194), (c < as_u32(245)) == false) {
                    s.error = true
                    s.pos = syntax.inc(s.pos)
                    return s
                }
                if c < as_u32(224) { s.pending = as_u32(1) }
                else if c < as_u32(240) { s.pending = as_u32(2) }
                else { s.pending = as_u32(3) }
                if c == as_u32(224) { s.low = as_u32(160) }
                if c == as_u32(237) { s.high = as_u32(160) }
                if c == as_u32(240) { s.low = as_u32(144) }
                if c == as_u32(244) { s.high = as_u32(144) }
            }
        }
        s.pos = syntax.inc(s.pos)
    }
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn validate(source: bytes.Bytes) -> syntax.Error {
    let zero = syntax.ZERO
    let mut s = Scan { pos: zero, pending: zero, lead: zero, low: zero, high: zero, error: false }
    for block in 0..64 {
        s = chunk(source, s)
        if s.error { return syntax.error(1, s.lead, s.pos) }
        if s.pos == bytes.len(source) {
            if (s.pending == zero) == false { return syntax.error(1, s.lead, s.pos) }
            return syntax.error(0, s.pos, s.pos)
        }
    }
    syntax.error(7, s.pos, s.pos)
}

lib/std/compiler/nox/check_scope.tri.source_text:
module std.compiler.nox.check_scope

use std.nox.seq
use std.compiler.nox.type_registry
use std.compiler.nox.constants
use std.compiler.nox.function_imports
use std.compiler.nox.syntax

// One immutable scope per checked function. Expressions share it while their
// lexical bindings change, without rebuilding the cold module metadata.
pub struct Scope {
    pub pure: Bool, pub types: type_registry.Scope,
    pub functions: seq.Seq, pub params: seq.Seq, pub constants: constants.Scope,
    pub function_start: U32, pub function_end: U32, pub imported_functions: function_imports.View
}

#[pure]
pub fn empty() -> Scope {
    local(false, type_registry.empty(), seq.empty(), seq.empty(), constants.empty())
}

// Whole-bank scope for the existing single-source and component entrypoints.
#[pure]
pub fn local(pure: Bool, types: type_registry.Scope, functions: seq.Seq, params: seq.Seq, constants: constants.Scope) -> Scope {
    Scope { pure, types, functions, params, constants, function_start: syntax.ZERO,
        function_end: seq.len(functions), imported_functions: function_imports.empty() }
}

lib/std/compiler/nox/record_assign.tri.source_text:
module std.compiler.nox.record_assign

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.expression
use std.compiler.nox.expression_state
use std.compiler.nox.body_state
use std.compiler.nox.blocks

struct Root { node: Noun, error: syntax.Error }

// Every accepted projection is a static field selection. Its stable LOCAL
// slot identifies the binding even when another name shadows an older slot.
#[pure]
fn root(nodes: seq.Seq, bindings: seq.Seq, lhs: U32) -> Root {
    let target = seq.get(nodes, lhs)
    let mut current = target
    for step in 0..65 {
        if ast.kind(current) == ast.LOCAL {
            let binding = seq.get(bindings, as_u32(ast.left(current)))
            if (noun.as_field(noun.head(noun.tail(binding))) == 1) == false {
                return Root { node: current, error: ast.issue(5, target) }
            }
            return Root { node: current, error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
        }
        if (ast.kind(current) == ast.PROJECT) == false { return Root { node: current, error: ast.issue(5, target) } }
        current = seq.get(nodes, as_u32(ast.left(current)))
    }
    Root { node: current, error: ast.issue(7, target) }
}

#[pure]
#[requires(lhs < seq.len(input.nodes))]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn assign(source: bytes.Bytes, input: body_state.State, lhs: U32, cap: U32) -> body_state.State {
    let mut s = input
    let target = seq.get(s.nodes, lhs)
    let selected = root(s.nodes, s.bindings, lhs)
    s.error = selected.error
    if (s.error.code == syntax.ZERO) == false { return s }
    if seq.len(s.statements) == cap { s.error = ast.issue(7, target) return s }
    let rhs = expression.parse(source, lexer.next(source, s.token.end), expression_state.context(s.bindings, s.visible, s.scope), s.nodes, s.arguments, s.edges, cap, false)
    s.error = rhs.error
    if (s.error.code == syntax.ZERO) == false { return s }
    let value = seq.get(rhs.nodes, rhs.value)
    if noun.eq(ast.ty(value), ast.ty(target)) == false { s.error = ast.issue(5, value) return s }
    if seq.len(rhs.nodes) == cap { s.error = ast.issue(7, value) return s }
    let edit = seq.len(rhs.nodes)
    s.nodes = seq.push(rhs.nodes, ast.typed(ast.RECORD_EDIT, as_field(lhs), as_field(rhs.value), ast.ty(selected.node), ast.start(target), ast.end(value)), cap)
    s.arguments = rhs.arguments
    s.edges = rhs.edges
    if rhs.needs_get { s.needs_get = true }
    s.token = rhs.token
    body_state.append(s, blocks.statement(blocks.WRITE, as_u32(ast.left(selected.node)), edit, syntax.ZERO), cap)
}

