module std.compiler.nox.array_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.expression_state

struct Frame { start: U32, base: U32, count: U32, head: U32 }

#[pure]
fn pack(f: Frame) -> Noun {
    let position = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.base)))
    let values = noun.pair(noun.atom(as_field(f.count)), noun.atom(as_field(f.head)))
    noun.pair(position, values)
}

#[pure]
fn read(value: Noun) -> Frame {
    let position = noun.head(value)
    let values = noun.tail(value)
    Frame { start: as_u32(noun.as_field(noun.head(position))), base: as_u32(noun.as_field(noun.tail(position))),
        count: as_u32(noun.as_field(noun.head(values))), head: as_u32(noun.as_field(noun.tail(values))) }
}

#[pure]
pub fn enter(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = ast.failed(s.token, 7) return s }
    let frame = Frame { start: s.token.start, base: s.vals, count: syntax.ZERO, head: signatures.NONE }
    s.frames = noun.pair(pack(frame), s.frames)
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(expression_state.ARRAY_MARKER)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.token = lexer.next(source, s.token.end)
    s.operand = true
    s
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool) -> expression_state.State {
    let mut s = input
    let mut f = read(noun.head(s.frames))
    if s.operand {
        // Both [] and a trailing comma after an element are valid.
        if closing == false { s.error = ast.failed(s.token, 2) return s }
    } else {
        if (s.vals == syntax.inc(f.base)) == false { s.error = ast.failed(s.token, 2) return s }
        let value = noun.as_field(seq.get(s.values, f.base))
        let node = seq.get(s.nodes, as_u32(value))
        if noun.eq(ast.ty(node), noun.atom(types.FIELD)) == false { s.error = ast.issue(6, node) return s }
        if syntax.either(syntax.inc(f.count) == s.node_cap, seq.len(s.arguments) == s.node_cap) {
            s.error = ast.failed(s.token, 7) return s
        }
        let link = seq.len(s.arguments)
        s.arguments = seq.push(s.arguments, noun.pair(noun.atom(value), noun.atom(as_field(f.head))), s.node_cap)
        f.head = link
        f.count = syntax.inc(f.count)
        s.vals = f.base
    }
    if closing {
        let built = types.array(f.count, s.node_cap, s.capacity)
        if built.failed { s.error = ast.failed(s.token, 7) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = ast.failed(s.token, 7) return s }
        let id = seq.len(s.nodes)
        s.nodes = seq.push(s.nodes, ast.typed(ast.ARRAY_VALUE, as_field(f.count), as_field(f.head), built.ty, f.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.operand = false
    } else {
        s.frames = noun.pair(pack(f), noun.tail(s.frames))
        s.operand = true
    }
    s.token = lexer.next(source, s.token.end)
    s
}

lib/std/compiler/nox/record_parse.tri.source_text:
module std.compiler.nox.record_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use vm.core.field
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.nominal
use std.compiler.nox.type_registry
use std.compiler.nox.record_frames
use std.compiler.nox.expression_state
use std.compiler.nox.qualified_name

// A constructor starts only with an uppercase type name and named-field syntax.
// A nested delimiter owns its braces even in an outer before-block expression.
#[pure]
pub fn starts(source: bytes.Bytes, name: syntax.Token, opening: syntax.Token, before_block: Bool, frames: Noun) -> Bool {
    if syntax.both(before_block, noun.eq(frames, noun.atom(0))) { return false }
    let first = bytes.get(source, name.start)
    if syntax.either(first < as_u32(65), (first < as_u32(91)) == false) { return false }
    let next = lexer.next(source, opening.end)
    if next.kind == as_u32(8) { return true }
    if (next.kind == as_u32(1)) == false { return false }
    let following = lexer.next(source, next.end)
    syntax.either(following.kind == as_u32(17), syntax.either(following.kind == as_u32(26), following.kind == as_u32(8)))
}

// This phase owns labels, colons and shorthand. Ordinary expression parsing
// owns the selected initializer, including every nested delimiter.
#[pure]
fn member(source: bytes.Bytes, input: expression_state.State, input_frame: record_frames.Frame) -> expression_state.State {
    let mut s = input
    let mut f = input_frame
    if s.token.kind == as_u32(8) {
        f.pending = signatures.NONE
        s.frames = noun.pair(record_frames.pack(f), noun.tail(s.frames))
        return s
    }
    if (s.token.kind == as_u32(1)) == false { s.error = ast.failed(s.token, 2) return s }
    let selected = record_frames.find(f, bytes.to_noun(type_registry.name(source, s.token)))
    if selected.index == signatures.NONE { s.error = ast.failed(s.token, 5) return s }
    if noun.eq(tree.get(f.values, f.arity, selected.index), noun.atom(0)) == false { s.error = ast.failed(s.token, 5) return s }
    f.pending = selected.index
    f.expected = selected.ty
    let following = lexer.next(source, s.token.end)
    if following.kind == as_u32(17) { s.token = lexer.next(source, following.end) }
    else if syntax.either(following.kind == as_u32(26), following.kind == as_u32(8)) == false {
        s.error = ast.failed(following, 2) return s
    }
    s.frames = noun.pair(record_frames.pack(f), noun.tail(s.frames))
    s
}

#[pure]
pub fn enter(source: bytes.Bytes, opening: syntax.Token, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let found = type_registry.lookup(s.context.scope.types, type_registry.name(source, s.token))
    if found.exists == false { s.error = ast.failed(s.token, 5) return s }
    enter_type(source, opening, s, found.ty)
}

#[pure]
pub fn enter_qualified(source: bytes.Bytes, query: qualified_name.Name, input: expression_state.State) -> expression_state.State {
    let mut s = input
    s.token = syntax.token(1, query.start, query.end, 0)
    let found = type_registry.imported(source, query, s.context.scope.types)
    if found.exists == false { s.error = ast.failed(s.token, 5) return s }
    enter_type(source, query.token, s, found.ty)
}

// Preserve the descriptor's defining owner and the full caller path span.
#[pure]
fn enter_type(source: bytes.Bytes, opening: syntax.Token, input: expression_state.State, ty: Noun) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = ast.failed(opening, 7) return s }
    let fields = nominal.fields(ty)
    let arity = seq.len(fields)
    let mut members = noun.atom(0)
    let values = tree.empty(tree.shape(arity).height)
    for index in 0..32 {
        if index < arity {
            let position = as_u32(field.sub(as_field(arity), as_field(index) + 1))
            let field = seq.get(fields, position)
            if syntax.both(nominal.field_public(field) == false, noun.eq(nominal.owner(ty), bytes.to_noun(s.context.scope.types.owner)) == false) {
                s.error = ast.failed(s.token, 5) return s
            }
            members = noun.pair(field, members)
        }
    }
    let f = record_frames.Frame { ty, fields: members, values, arity, expected: noun.atom(0), start: s.token.start, base: s.vals, count: syntax.ZERO, pending: signatures.NONE }
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(expression_state.RECORD_MARKER)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.frames = noun.pair(noun.atom(0), s.frames)
    s.token = lexer.next(source, opening.end)
    member(source, s, f)
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool) -> expression_state.State {
    let mut s = input
    let mut f = record_frames.read(noun.head(s.frames))
    if s.operand == false {
        if (s.vals == syntax.inc(f.base)) == false { s.error = ast.failed(s.token, 2) return s }
        let id = as_u32(noun.as_field(seq.get(s.values, f.base)))
        let value = seq.get(s.nodes, id)
        if (noun.eq(ast.ty(value), f.expected)) == false { s.error = ast.issue(5, value) return s }
        f.values = tree.set(f.values, f.arity, f.pending, noun.atom(as_field(id) + 1))
        f.count = syntax.inc(f.count)
        s.vals = f.base
    } else if syntax.either(closing == false, (f.pending == signatures.NONE) == false) { s.error = ast.failed(s.token, 2) return s }
    if closing {
        if (f.count == f.arity) == false { s.error = syntax.error(5, f.start, s.token.end) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = ast.failed(s.token, 7) return s }
        let mut head = signatures.NONE
        // Formula links follow declaration order, independent of source labels.
        for index in 0..32 {
            if index < f.count {
                if seq.len(s.arguments) == s.node_cap { s.error = ast.failed(s.token, 7) return s }
                let link = seq.len(s.arguments)
                s.arguments = seq.push(s.arguments, noun.pair(noun.atom(field.sub(noun.as_field(tree.get(f.values, f.arity, index)), 1)), noun.atom(as_field(head))), s.node_cap)
                head = link
            }
        }
        let id = seq.len(s.nodes)
        s.nodes = seq.push(s.nodes, ast.typed(ast.RECORD_VALUE, as_field(f.count), as_field(head), f.ty, f.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.operand = false
        s.token = lexer.next(source, s.token.end)
        return s
    }
    s.operand = true
    s.token = lexer.next(source, s.token.end)
    member(source, s, f)
}

#[pure]
pub fn project(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = ast.failed(name, 2) return s }
    let base = as_u32(noun.as_field(seq.get(s.values, syntax.dec(s.vals))))
    let value = seq.get(s.nodes, base)
    let selected = nominal.lookup(ast.ty(value), s.context.scope.types.owner, type_registry.name(source, name))
    if syntax.either(selected.exists == false, selected.visible == false) { s.error = ast.failed(name, 5) return s }
    if seq.len(s.nodes) == s.node_cap { s.error = ast.failed(name, 7) return s }
    let mut axis: Field = 2
    for index in 0..32 { if index < selected.index { axis = axis * 2 + 2 } }
    let id = seq.len(s.nodes)
    s.nodes = seq.push(s.nodes, ast.typed(ast.PROJECT, as_field(base), axis, selected.ty, ast.start(value), name.end), s.node_cap)
    s.values = seq.set(s.values, syntax.dec(s.vals), noun.atom(as_field(id)))
    s.token = lexer.next(source, name.end)
    s
}

lib/std/compiler/nox/attributes.tri.source_text:
module std.compiler.nox.attributes

use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.lexer

pub const HASH: U32 = 46
pub struct Parsed { pub token: syntax.Token, pub error: syntax.Error, pub pure: Bool }
struct Payload { token: syntax.Token, depth: U32, error: syntax.Error }

#[pure]
fn expected(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
fn kind(source: bytes.Bytes, name: syntax.Token) -> Field {
    if name.value == 1886745189 { return 1 } // pure
    if name.value == 28550414818502003 { return 2 } // ensures
    if (field.sub(as_field(name.end), as_field(name.start)) == 8) == false { return 0 }
    let spelling = [114,101,113,117,105,114,101,115] // requires
    for i in 0..8 {
        if (as_field(bytes.get(source, as_u32(as_field(name.start) + as_field(i)))) == spelling[i]) == false { return 0 }
    }
    2
}

// The seed collects lexical metadata, balancing parentheses alone. No source
// expression is checked or executed here; its delimiter stack is independent.
#[pure]
fn payload(source: bytes.Bytes, opening: syntax.Token) -> Payload {
    let mut s = Payload { token: lexer.next(source, opening.end), depth: as_u32(1), error: syntax.error(0, opening.start, opening.end) }
    for turn in 0..4096 {
        if syntax.either(s.token.kind == syntax.ZERO, s.token.kind == as_u32(14)) { s.error = expected(s.token) return s }
        // asm has a special lexer in the seed, including inside attributes.
        if syntax.both(s.token.kind == as_u32(13), s.token.value == 6386541) { s.error = syntax.error(6, s.token.start, s.token.end) return s }
        if s.token.kind == as_u32(5) { s.depth = syntax.inc(s.depth) }
        if s.token.kind == as_u32(6) {
            s.depth = syntax.dec(s.depth)
            if s.depth == syntax.ZERO { s.token = lexer.next(source, s.token.end) return s }
        }
        s.token = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

#[pure]
fn one(source: bytes.Bytes, input: Parsed) -> Parsed {
    let mut s = input
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(36)) == false { s.error = expected(s.token) return s }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    let attribute = kind(source, name)
    if attribute == 0 { s.error = syntax.error(6, name.start, name.end) return s }
    s.token = lexer.next(source, name.end)
    if attribute == 1 {
        if s.token.kind == as_u32(5) { s.error = syntax.error(6, name.start, s.token.end) return s }
        s.pure = true
    } else {
        if (s.token.kind == as_u32(5)) == false {
            if s.token.kind == as_u32(37) { s.error = syntax.error(6, name.start, s.token.end) }
            else { s.error = expected(s.token) }
            return s
        }
        let collected = payload(source, s.token)
        s.token = collected.token
        s.error = collected.error
        if (s.error.code == syntax.ZERO) == false { return s }
    }
    if (s.token.kind == as_u32(37)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn parse(source: bytes.Bytes, start: syntax.Token) -> Parsed {
    let mut s = Parsed { token: start, error: syntax.error(0, start.start, start.end), pure: false }
    for turn in 0..4096 {
        if (s.token.kind == HASH) == false { return s }
        s = one(source, s)
        if (s.error.code == syntax.ZERO) == false { return s }
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

lib/std/compiler/nox/struct_parse.tri.source_text:
module std.compiler.nox.struct_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.nominal
use std.compiler.nox.type_registry
use std.compiler.nox.type_parse

pub struct Parsed { pub scope: type_registry.Scope, pub token: syntax.Token, pub error: syntax.Error }

#[pure]
fn failed(scope: type_registry.Scope, token: syntax.Token, code: Field) -> Parsed {
    Parsed { scope, token, error: ast.failed(token, code) }
}

// Register only a complete layout. Field types resolve against the preceding
// registry, so a declaration cannot refer to itself or a later layout.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.SOURCE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, opening: syntax.Token, scope: type_registry.Scope, public: Bool, cap: U32) -> Parsed {
    let name_token = lexer.next(source, opening.end)
    if (name_token.kind == as_u32(1)) == false { return failed(scope, name_token, 2) }
    if seq.len(scope.records) == cap { return failed(scope, name_token, 7) }
    let name = type_registry.name(source, name_token)
    let previous = type_registry.lookup(scope, name)
    let mut token = lexer.next(source, name_token.end)
    if (token.kind == as_u32(7)) == false { return failed(scope, token, 2) }
    token = lexer.next(source, token.end)
    let mut members = seq.empty()
    let mut spans = seq.empty()
    for index in 0..33 {
        if token.kind == as_u32(8) {
            let built = nominal.build(scope.owner, name, members, cap, syntax.STACK_CAP)
            if (built.status == syntax.ZERO) == false {
                let mut at = name_token
                if built.field < seq.len(spans) {
                    let span = seq.get(spans, built.field)
                    at = syntax.token(1, as_u32(noun.as_field(noun.head(span))), as_u32(noun.as_field(noun.tail(span))), 0)
                }
                return failed(scope, at, as_field(built.status))
            }
            if previous.exists {
                if noun.eq(previous.ty, built.ty) == false { return failed(scope, name_token, 5) }
            }
            let mut result = scope
            result.records = seq.push(result.records, type_registry.record(built.ty, public), cap)
            return Parsed { scope: result, token: lexer.next(source, token.end), error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
        }
        let mut visible = false
        if token.kind == as_u32(40) { visible = true token = lexer.next(source, token.end) }
        let field_token = token
        if (field_token.kind == as_u32(1)) == false { return failed(scope, field_token, 2) }
        if syntax.either(index == nominal.MAX_FIELDS, seq.len(members) == cap) { return failed(scope, field_token, 7) }
        token = lexer.next(source, token.end)
        if (token.kind == as_u32(17)) == false { return failed(scope, token, 2) }
        token = lexer.next(source, token.end)
        let parsed = type_parse.parse(source, token, scope, cap)
        if (parsed.error.code == syntax.ZERO) == false { return Parsed { scope, token: parsed.token, error: parsed.error } }
        members = seq.push(members, nominal.field(type_registry.name(source, field_token), parsed.ty, visible), cap)
        spans = seq.push(spans, noun.pair(noun.atom(as_field(field_token.start)), noun.atom(as_field(field_token.end))), cap)
        token = parsed.token
        if token.kind == as_u32(26) { token = lexer.next(source, token.end) }
        else if (token.kind == as_u32(8)) == false { return failed(scope, token, 2) }
    }
    failed(scope, token, 7)
}

