module std.compiler.nox.code_plan

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.body_store
use std.compiler.nox.function_plan
use std.compiler.nox.signatures

// Functions retain their old slots; loops follow, grouped by sorted owner.
pub struct Plan { pub count: U32, pub bases: Noun, pub next: U32, pub failed: Bool, pub needs_get: Bool, pub get_slot: U32 }

#[pure]
fn chunk(bodies: seq.Seq, functions: function_plan.Plan, input: Plan, cap: U32) -> Plan {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(functions.order) { return s }
        let owner = as_u32(noun.as_field(seq.get(functions.order, s.next)))
        let stored = seq.get(bodies, owner)
        if body_store.needs_get(stored) { s.needs_get = true }
        let count = body_store.loop_count(stored)
        let total = as_u32(as_field(s.count) + as_field(count))
        if cap < total { s.failed = true return s }
        s.bases = tree.set(s.bases, seq.len(bodies), owner, noun.atom(as_field(s.count)))
        s.count = total
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
fn finish(input: Plan, cap: U32) -> Plan {
    let mut s = input
    if s.needs_get {
        if (s.count < cap) == false { s.failed = true return s }
        s.get_slot = s.count
        s.count = syntax.inc(s.count)
    }
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < cap) == false)]
pub fn extend(bodies: seq.Seq, functions: function_plan.Plan, cap: U32) -> Plan {
    let mut s = Plan { count: seq.len(functions.order), bases: tree.empty(tree.shape(seq.len(bodies)).height),
        next: syntax.ZERO, failed: cap < seq.len(functions.order), needs_get: false, get_slot: signatures.NONE }
    for turn in 0..512 {
        if s.failed { return s }
        if s.next == seq.len(functions.order) { return finish(s, cap) }
        s = chunk(bodies, functions, s, cap)
    }
    if (s.next == seq.len(functions.order)) == false { s.failed = true return s }
    finish(s, cap)
}

lib/std/compiler/nox/constant_exports.tr.source_text:
module std.compiler.nox.constant_exports

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax

// Export IDs are stable across dependency modules. Linked lists index only
// final public bindings; source spans always belong to their recorded owner.
pub struct Bank { records: seq.Seq, heads: Noun, modules: U32 }
pub struct Binding {
    pub owner: U32, pub name: syntax.Token, pub ty: Field, pub value: Field,
    pub literal_owner: U32, pub literal: syntax.Token
}
pub struct Found { pub exists: Bool, pub id: U32 }

#[pure]
pub fn empty(modules: U32) -> Bank {
    Bank { records: seq.empty(), heads: tree.empty(tree.shape(modules).height), modules }
}

#[pure]
pub fn len(bank: Bank) -> U32 { seq.len(bank.records) }

#[pure]
fn span(token: syntax.Token) -> Noun {
    noun.pair(noun.atom(as_field(token.start)), noun.atom(as_field(token.end)))
}

#[pure]
fn token(value: Noun, kind: Field, literal: Field) -> syntax.Token {
    syntax.token(kind, as_u32(noun.as_field(noun.head(value))), as_u32(noun.as_field(noun.tail(value))), literal)
}

#[pure]
#[requires(id < len(bank))]
pub fn read(bank: Bank, id: U32) -> Binding {
    let row = noun.tail(seq.get(bank.records, id))
    let name = noun.tail(row)
    let ty = noun.tail(name)
    let value = noun.tail(ty)
    let origin = noun.tail(value)
    let number = noun.as_field(noun.head(value))
    Binding { owner: as_u32(noun.as_field(noun.head(row))), name: token(noun.head(name), 1, 0),
        ty: noun.as_field(noun.head(ty)), value: number,
        literal_owner: as_u32(noun.as_field(noun.head(origin))), literal: token(noun.tail(origin), 2, number) }
}

// Callers check source-work capacity before publishing. The bank keeps its own
// typed storage and never admits externally supplied serialized record handles.
#[pure]
#[requires(len(bank) < cap)]
pub fn push(bank: Bank, item: Binding, cap: U32) -> Bank {
    assert(item.owner < bank.modules)
    assert(item.literal_owner < bank.modules)
    let id = len(bank)
    let next = tree.get(bank.heads, bank.modules, item.owner)
    let origin = noun.pair(noun.atom(as_field(item.literal_owner)), span(item.literal))
    let value = noun.pair(noun.atom(item.value), origin)
    let row = noun.pair(noun.atom(as_field(item.owner)), noun.pair(span(item.name), noun.pair(noun.atom(item.ty), value)))
    Bank { records: seq.push(bank.records, noun.pair(next, row), cap),
        heads: tree.set(bank.heads, bank.modules, item.owner, noun.atom(as_field(id) + 1)), modules: bank.modules }
}

// Two independent source buffers prevent a foreign declaration's offsets from
// accidentally selecting unrelated bytes in the importing source.
#[pure]
fn same(caller: bytes.Bytes, query: syntax.Token, source: bytes.Bytes, name: syntax.Token) -> Bool {
    if (field.sub(as_field(query.end), as_field(query.start)) == field.sub(as_field(name.end), as_field(name.start))) == false { return false }
    let mut a = query.start
    let mut b = name.start
    for step in 0..4096 {
        if a == query.end { return true }
        if (bytes.get(caller, a) == bytes.get(source, b)) == false { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    a == query.end
}

#[pure]
#[requires(owner < bank.modules)]
#[requires((syntax.SOURCE_CAP < len(bank)) == false)]
pub fn find(bank: Bank, owner: U32, source: bytes.Bytes, caller: bytes.Bytes, query: syntax.Token) -> Found {
    let mut cursor = as_u32(noun.as_field(tree.get(bank.heads, bank.modules, owner)))
    for step in 0..4096 {
        if cursor == syntax.ZERO { return Found { exists: false, id: syntax.ZERO } }
        let id = syntax.dec(cursor)
        let binding = read(bank, id)
        if same(caller, query, source, binding.name) { return Found { exists: true, id } }
        cursor = as_u32(noun.as_field(noun.head(seq.get(bank.records, id))))
    }
    Found { exists: false, id: syntax.ZERO }
}

lib/std/compiler/nox/function_plan.tri.source_text:
module std.compiler.nox.function_plan

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.nox.bytes
use std.compiler.nox.signatures
use std.compiler.nox.syntax
use std.compiler.nox.function_order
use std.compiler.nox.call_graph

pub struct Plan { pub order: seq.Seq, pub slots: Noun, pub next: U32, pub error: syntax.Error, pub error_function: U32 }

#[pure]
fn chunk(ordered: seq.Seq, reachable: Noun, functions: U32, input: Plan, cap: U32) -> Plan {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(ordered) { return s }
        let value = seq.get(ordered, s.next)
        let id = as_u32(noun.as_field(value))
        if noun.as_field(tree.get(reachable, functions, id)) == 2 {
            if seq.len(s.order) == cap { s.error = syntax.error(7, syntax.ZERO, syntax.ZERO) return s }
            // Zero is absent. Occupied table indices are stored plus one.
            s.slots = tree.set(s.slots, functions, id, noun.atom(as_field(seq.len(s.order)) + 1))
            s.order = seq.push(s.order, value, cap)
        }
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires(entry < seq.len(functions))]
pub fn plan(source: bytes.Bytes, functions: seq.Seq, bodies: seq.Seq, entry: U32, cap: U32) -> Plan {
    ordered(functions, bodies, function_order.sort(source, functions, cap), entry, cap)
}

#[pure]
#[requires(entry < seq.len(functions))]
pub fn ordered(functions: seq.Seq, bodies: seq.Seq, sorted: function_order.Ordered, entry: U32, cap: U32) -> Plan {
    let zero = syntax.ZERO
    let mut s = Plan { order: seq.empty(), slots: tree.empty(tree.shape(seq.len(functions)).height),
        next: zero, error: syntax.error(0, zero, zero), error_function: signatures.NONE }
    if cap == zero { s.error = syntax.error(7, zero, zero) return s }
    s.error = sorted.error
    if (s.error.code == zero) == false { return s }
    let checked = call_graph.walk(functions, bodies, sorted.ids, cap)
    s.error = checked.error
    s.error_function = checked.error_function
    if (s.error.code == zero) == false { return s }
    let roots = seq.push(seq.empty(), noun.atom(as_field(entry)), cap)
    let reachable = call_graph.walk(functions, bodies, roots, cap)
    s.error = reachable.error
    s.error_function = reachable.error_function
    if (s.error.code == zero) == false { return s }
    for turn in 0..512 {
        s = chunk(sorted.ids, reachable.colors, seq.len(functions), s, cap)
        if syntax.either(s.next == seq.len(sorted.ids), (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

lib/std/compiler/nox/coverage.tri.source_text:
module std.compiler.nox.coverage

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.blocks
use std.compiler.nox.terminal
use std.compiler.nox.body_state
use std.compiler.nox.loop_records
use std.compiler.nox.types
use std.compiler.nox.halting

pub struct Checked { pub flags: Noun, pub error: syntax.Error }
struct State { flags: Noun, next: U32 }
struct Block { covered: Bool, remaining: Noun }

#[pure]
fn statement(s: blocks.Statement, nodes: seq.Seq, arguments: seq.Seq, flags: Noun, count: U32, loops: seq.Seq) -> Bool {
    if s.kind == blocks.RETURN { return true }
    if s.kind == blocks.EVAL { return halting.is_false_assert(seq.get(nodes, s.a), nodes, arguments) }
    if s.kind == blocks.FOR {
        let record = loop_records.read(seq.get(loops, s.a))
        if record.end == 4294967296 { return false }
        return syntax.both(loop_records.nonempty(record), noun.as_field(tree.get(flags, count, record.body)) == 1)
    }
    if (s.kind == blocks.IF) == false { return false }
    let yes = noun.as_field(tree.get(flags, count, s.b)) == 1
    let mut no = false
    if (s.c == blocks.NONE) == false { no = noun.as_field(tree.get(flags, count, s.c)) == 1 }
    let condition = seq.get(nodes, s.a)
    if syntax.either(ast.kind(condition) == ast.LITERAL, syntax.either(ast.kind(condition) == ast.BOOLEAN, ast.kind(condition) == ast.CONSTANT)) {
        if ast.left(condition) == 0 { return yes }
        return no
    }
    syntax.both(yes, no)
}

#[pure]
fn statement_chunk(input: Block, nodes: seq.Seq, statements: seq.Seq, arguments: seq.Seq, flags: Noun, count: U32, loops: seq.Seq) -> Block {
    let mut s = input
    for turn in 0..8 {
        if noun.eq(s.remaining, noun.atom(0)) { return s }
        let id = as_u32(noun.as_field(noun.head(s.remaining)))
        s.covered = syntax.either(s.covered, statement(blocks.read_statement(seq.get(statements, id)), nodes, arguments, flags, count, loops))
        s.remaining = noun.tail(s.remaining)
    }
    s
}

#[pure]
fn block(body: blocks.Block, terminal: Bool, nodes: seq.Seq, statements: seq.Seq, arguments: seq.Seq, flags: Noun, count: U32, loops: seq.Seq) -> Bool {
    let mut s = Block { covered: syntax.both(body.has_tail, terminal), remaining: body.statements }
    if body.has_tail {
        if terminal == false { s.covered = halting.is_false_assert(seq.get(nodes, body.tail), nodes, arguments) }
    }
    // All statements and terminal tails have already been type checked. Once
    // the tail covers this block, scanning earlier statements adds no evidence.
    if s.covered { return true }
    for turn in 0..512 {
        s = statement_chunk(s, nodes, statements, arguments, flags, count, loops)
        if noun.eq(s.remaining, noun.atom(0)) { return s.covered }
    }
    // Source-built lists contain at most SOURCE_CAP statement records.
    false
}

#[pure]
fn chunk(input: State, s: body_state.State, terminal: Noun) -> State {
    let mut state = input
    let count = seq.len(s.blocks)
    for turn in 0..8 {
        if state.next == count { return state }
        let tail_returns = noun.as_field(tree.get(terminal, count, state.next)) == 1
        let covered = block(blocks.read(seq.get(s.blocks, state.next)), tail_returns, s.nodes, s.statements, s.arguments, state.flags, count, s.loops)
        state.flags = tree.set(state.flags, count, state.next, blocks.flag(covered))
        state.next = syntax.inc(state.next)
    }
    state
}

// Type-check every terminal tail before coverage, including unselected arms.
#[pure]
#[requires(s.root < seq.len(s.blocks))]
pub fn check(s: body_state.State) -> Checked {
    let zero = syntax.ZERO
    let marked = terminal.mark(s.nodes, s.statements, s.blocks, s.arguments, s.root, s.returns)
    if (marked.error.code == zero) == false { return Checked { flags: marked.flags, error: marked.error } }
    let mut state = State { flags: tree.empty(tree.shape(seq.len(s.blocks)).height), next: zero }
    for turn in 0..512 {
        state = chunk(state, s, marked.flags)
        if state.next == seq.len(s.blocks) {
            if noun.eq(s.returns, noun.atom(types.UNIT)) { return Checked { flags: marked.flags, error: syntax.error(0, zero, zero) } }
            if noun.as_field(tree.get(state.flags, seq.len(s.blocks), s.root)) == 1 { return Checked { flags: marked.flags, error: syntax.error(0, zero, zero) } }
            let root = blocks.read(seq.get(s.blocks, s.root))
            return Checked { flags: marked.flags, error: syntax.error(5, root.start, root.end) }
        }
    }
    Checked { flags: marked.flags, error: syntax.error(7, zero, zero) }
}

