module std.compiler.nox.loop_parse

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.symbols
use std.compiler.nox.blocks
use std.compiler.nox.contexts
use std.compiler.nox.body_state
use std.compiler.nox.loop_records
use std.compiler.nox.types

struct Bound { value: Field, error: syntax.Error }

// Tokens normalize decimal values in Goldilocks. Loop candidates instead use
// their raw decimal range, including the exclusive end 2^32.
#[pure]
#[requires(syntax.either(last_digit == as_u32(5), last_digit == as_u32(6)))]
fn bound(source: bytes.Bytes, token: syntax.Token, last_digit: U32) -> Bound {
    let mut result = Bound { value: 0, error: syntax.error(0, token.start, token.end) }
    if (token.kind == as_u32(2)) == false {
        let mut code: Field = 2
        if syntax.either(token.kind == as_u32(1), token.kind == as_u32(5)) { code = 6 }
        if syntax.either(token.kind == as_u32(21), token.kind == as_u32(22)) { code = 5 }
        result.error = ast.failed(token, code)
        return result
    }
    let mut pos = token.start
    for turn in 0..4096 {
        if pos == token.end { return result }
        let digit = as_u32(field.sub(as_field(bytes.get(source, pos)), 48))
        if result.value == 4294967296 { result.error = syntax.error(5, token.start, token.end) return result }
        let value = as_u32(result.value)
        if syntax.either(as_u32(429496729) < value,
            syntax.both(value == as_u32(429496729), last_digit < digit)) {
            result.error = syntax.error(5, token.start, token.end)
            return result
        }
        result.value = result.value * 10 + as_field(digit)
        pos = syntax.inc(pos)
    }
    result.error = syntax.error(7, token.start, token.end)
    result
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn enter(source: bytes.Bytes, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    let mut nesting = cap
    if syntax.STACK_CAP < nesting { nesting = syntax.STACK_CAP }
    if syntax.either(nesting == syntax.ZERO, syntax.inc(s.depth) == nesting) {
        s.error = syntax.error(7, s.token.start, s.token.end)
        return s
    }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = ast.failed(name, 2) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(32)) == false { s.error = ast.failed(s.token, 2) return s }
    s.token = lexer.next(source, s.token.end)
    let first = bound(source, s.token, as_u32(5))
    s.error = first.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(33)) == false { s.error = ast.failed(s.token, 2) return s }
    s.token = lexer.next(source, s.token.end)
    let end = bound(source, s.token, as_u32(6))
    s.error = end.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(7)) == false { s.error = ast.failed(s.token, 2) return s }
    if syntax.either(seq.len(s.loops) == cap, cap < as_u32(as_field(seq.len(s.bindings)) + 2)) {
        s.error = syntax.error(7, name.start, s.token.end)
        return s
    }
    let id = seq.len(s.loops)
    let index = seq.len(s.bindings)
    let record = loop_records.Loop { index, remaining: syntax.inc(index), first: first.value, end: end.value, body: blocks.NONE }
    s.loops = seq.push(s.loops, loop_records.pack(record), cap)
    let frame = contexts.Frame { statements: s.current, visible: s.visible, returned: s.returned,
        synthetic: s.synthetic, start: s.start, condition: id, then_block: blocks.NONE, phase: 2 }
    s.frames = noun.pair(contexts.pack(frame), s.frames)
    s.depth = syntax.inc(s.depth)
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, noun.atom(types.UINT32)), cap)
    // The remaining count can be 2^32. It is an invisible Field slot.
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, noun.atom(types.FIELD)), cap)
    s.visible = noun.pair(noun.atom(as_field(index)), s.visible)
    s.start = s.token.start
    s.token = lexer.next(source, s.token.end)
    s.current = noun.atom(0)
    s.synthetic = false
    s.returned = false
    s.has_tail = false
    s
}

lib/std/compiler/nox/ast.tri.source_text:
module std.compiler.nox.ast

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.types

pub const LITERAL: Field = 0
pub const LOCAL: Field = 1
pub const BOOLEAN: Field = 2
pub const ADD: Field = 3
pub const MUL: Field = 4
pub const EQUAL: Field = 5
pub const CALL: Field = 6
pub const UNIT_VALUE: Field = 7
pub const LESS: Field = 8
pub const BIT_AND: Field = 9
pub const BUILTIN: Field = 10
pub const DIGEST_INDEX: Field = 11
pub const TUPLE_VALUE: Field = 12
pub const PROJECT: Field = 13
pub const RECORD_VALUE: Field = 14
pub const RECORD_EDIT: Field = 15
pub const ARRAY_VALUE: Field = 16
pub const ARRAY_INDEX: Field = 17
pub const CONSTANT: Field = 18

// Postorder expression: [[kind [left right]] [type [start end]]].
// Child IDs precede their parent. AST operations are independent of token kinds.
#[pure]
pub fn typed(kind: Field, left: Field, right: Field, ty: Noun, start: U32, end: U32) -> Noun {
    let value = noun.pair(noun.atom(kind), noun.pair(noun.atom(left), noun.atom(right)))
    let span = noun.pair(noun.atom(as_field(start)), noun.atom(as_field(end)))
    noun.pair(value, noun.pair(ty, span))
}

// Internal component builders can omit source spans.
#[pure]
pub fn node(kind: Field, left: Field, right: Field) -> Noun {
    let mut ty = noun.atom(types.FIELD)
    if syntax.either(kind == BOOLEAN, kind == EQUAL) { ty = noun.atom(types.BOOL) }
    if kind == UNIT_VALUE { ty = noun.atom(types.UNIT) }
    if kind == LESS { ty = noun.atom(types.BOOL) }
    if kind == BIT_AND { ty = noun.atom(types.UINT32) }
    typed(kind, left, right, ty, syntax.ZERO, syntax.ZERO)
}

#[pure]
pub fn kind(node: Noun) -> Field { noun.as_field(noun.head(noun.head(node))) }

#[pure]
pub fn left(node: Noun) -> Field { noun.as_field(noun.head(noun.tail(noun.head(node)))) }

#[pure]
pub fn right(node: Noun) -> Field { noun.as_field(noun.tail(noun.tail(noun.head(node)))) }

#[pure]
pub fn ty(node: Noun) -> Noun { noun.head(noun.tail(node)) }

#[pure]
pub fn start(node: Noun) -> U32 { as_u32(noun.as_field(noun.head(noun.tail(noun.tail(node))))) }

#[pure]
pub fn end(node: Noun) -> U32 { as_u32(noun.as_field(noun.tail(noun.tail(noun.tail(node))))) }

#[pure]
pub fn issue(code: Field, node: Noun) -> syntax.Error { syntax.error(code, start(node), end(node)) }

#[pure]
pub fn store(stack: seq.Seq, length: U32, value: Noun, cap: U32) -> seq.Seq {
    if length < seq.len(stack) { return seq.set(stack, length, value) }
    seq.push(stack, value, cap)
}

#[pure]
pub fn failed(token: syntax.Token, fallback: Field) -> syntax.Error {
    if token.kind == as_u32(46) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(45) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(43) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(41), syntax.either(token.kind == as_u32(39), token.kind == as_u32(40))) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(35) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(34), token.kind == as_u32(28)) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(20), token.kind == as_u32(23)) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    if syntax.either(syntax.either(syntax.either(token.kind == as_u32(13), token.kind == as_u32(10)), token.kind == as_u32(11)), token.kind == as_u32(12)) {
        return syntax.error(6, token.start, token.end)
    }
    syntax.error(fallback, token.start, token.end)
}

lib/std/compiler/nox/tuple_pattern.tri.source_text:
module std.compiler.nox.tuple_pattern

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.types

pub struct Parsed { pub names: seq.Seq, pub token: syntax.Token, pub error: syntax.Error }

#[pure]
pub fn discard(token: syntax.Token) -> Bool {
    syntax.both(token.kind == as_u32(13), token.value == 95)
}

#[pure]
pub fn pack(token: syntax.Token) -> Noun {
    let mut flag: Field = 0
    if discard(token) { flag = 1 }
    noun.pair(noun.atom(as_field(token.start)), noun.pair(noun.atom(as_field(token.end)), noun.atom(flag)))
}

#[pure]
pub fn name(record: Noun) -> syntax.Token {
    let end = noun.tail(record)
    let mut kind: Field = 1
    let mut value: Field = 0
    if noun.as_field(noun.tail(end)) == 1 { kind = 13 value = 95 }
    syntax.token(kind, as_u32(noun.as_field(noun.head(record))), as_u32(noun.as_field(noun.head(end))), value)
}

// Called just after the opening parenthesis. The seed accepts a trailing comma
// and empty pattern syntax; component-count validation belongs to the binder.
#[pure]
pub fn parse(source: bytes.Bytes, token: syntax.Token, cap: U32) -> Parsed {
    let zero = syntax.ZERO
    let mut s = Parsed { names: seq.empty(), token, error: syntax.error(0, zero, zero) }
    for i in 0..17 {
        if s.token.kind == as_u32(6) { s.token = lexer.next(source, s.token.end) return s }
        if syntax.either(s.token.kind == as_u32(1), discard(s.token)) == false {
            s.error = ast.failed(s.token, 2) return s
        }
        if syntax.either(seq.len(s.names) == cap, seq.len(s.names) == types.MAX_ARITY) {
            s.error = ast.failed(s.token, 7) return s
        }
        s.names = seq.push(s.names, pack(s.token), cap)
        s.token = lexer.next(source, s.token.end)
        if s.token.kind == as_u32(6) { s.token = lexer.next(source, s.token.end) return s }
        if (s.token.kind == as_u32(26)) == false { s.error = ast.failed(s.token, 2) return s }
        s.token = lexer.next(source, s.token.end)
    }
    s.error = ast.failed(s.token, 7)
    s
}

