module std.compiler.nox.entry_frame

use vm.nox.noun
use vm.core.convert
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.formula
use std.compiler.nox.flow

// The original runtime subject occupies leaf zero. Padding is quoted data;
// each CONS evaluates against that same original subject before dispatch.
#[pure]
#[requires((as_u32(32) < height) == false)]
pub fn subject(table: formula.Value, height: U32) -> formula.Value {
    let mut frame = flow.axis(1)
    for level in 0..32 {
        if level == height { return formula.pair(table, formula.pair(flow.literal(0), frame)) }
        let padding = formula.Value { formula: noun.pair(noun.atom(1), tree.empty(level)), depth: syntax.inc(level) }
        frame = formula.pair(frame, padding)
    }
    formula.pair(table, formula.pair(flow.literal(0), frame))
}

lib/std/compiler/nox/contexts.tri.source_text:
module std.compiler.nox.contexts

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.blocks

// A frame remembers its parent list/scope while one conditional arm is parsed.
// Phase0 awaits then; phase1 awaits else; phase2 owns a loop in condition.
// Synthetic else-if blocks close without
// consuming an extra source brace, using the same ownership as the seed parser.
pub struct Frame {
    pub statements: Noun, pub visible: Noun, pub returned: Bool,
    pub synthetic: Bool, pub start: U32, pub condition: U32,
    pub then_block: U32, pub phase: Field
}

#[pure]
pub fn pack(f: Frame) -> Noun {
    let environment = noun.pair(f.statements, f.visible)
    let flags = noun.pair(blocks.flag(f.returned), blocks.flag(f.synthetic))
    let owner = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.condition)))
    let arms = noun.pair(noun.atom(as_field(f.then_block)), noun.atom(f.phase))
    noun.pair(noun.pair(environment, flags), noun.pair(owner, arms))
}

#[pure]
pub fn read(value: Noun) -> Frame {
    let parent = noun.head(value)
    let environment = noun.head(parent)
    let flags = noun.tail(parent)
    let child = noun.tail(value)
    let owner = noun.head(child)
    let arms = noun.tail(child)
    Frame { statements: noun.head(environment), visible: noun.tail(environment),
        returned: noun.as_field(noun.head(flags)) == 1, synthetic: noun.as_field(noun.tail(flags)) == 1,
        start: as_u32(noun.as_field(noun.head(owner))), condition: as_u32(noun.as_field(noun.tail(owner))),
        then_block: as_u32(noun.as_field(noun.head(arms))), phase: noun.as_field(noun.tail(arms)) }
}

lib/std/compiler/nox/call_graph.tri.source_text:
module std.compiler.nox.call_graph

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.body_store

pub const DEPTH_CAP: U32 = 128
pub struct Walked {
    pub colors: Noun, pub heights: Noun, pub frames: Noun, pub depth: U32, pub next: U32,
    pub done: Bool, pub error: syntax.Error, pub error_function: U32
}

#[pure]
fn push(functions: seq.Seq, bodies: seq.Seq, input: Walked, id: U32, cap: U32) -> Walked {
    let mut s = input
    let mut limit = cap
    if DEPTH_CAP < limit { limit = DEPTH_CAP }
    if s.depth == limit {
        let declaration = signatures.read(seq.get(functions, id))
        s.error = syntax.error(7, declaration.name.start, declaration.name.end)
        s.error_function = id
        return s
    }
    s.colors = tree.set(s.colors, seq.len(functions), id, noun.atom(1))
    let frame = noun.pair(noun.atom(as_field(id)), noun.pair(body_store.edges(seq.get(bodies, id)), noun.atom(0)))
    s.frames = noun.pair(frame, s.frames)
    s.depth = syntax.inc(s.depth)
    s
}

// Remember the longest completed child, including memoized shared suffixes.
#[pure]
fn remember(input: Walked, height: U32) -> Walked {
    let mut s = input
    if noun.eq(s.frames, noun.atom(0)) { return s }
    let frame = noun.head(s.frames)
    let rest = noun.tail(frame)
    let old = as_u32(noun.as_field(noun.tail(rest)))
    if old < height {
        let changed = noun.pair(noun.head(frame), noun.pair(noun.head(rest), noun.atom(as_field(height))))
        s.frames = noun.pair(changed, noun.tail(s.frames))
    }
    s
}

#[pure]
fn step(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, input: Walked, cap: U32) -> Walked {
    let mut s = input
    if noun.eq(s.frames, noun.atom(0)) {
        if s.next == seq.len(roots) { s.done = true return s }
        let id = as_u32(noun.as_field(seq.get(roots, s.next)))
        s.next = syntax.inc(s.next)
        if noun.as_field(tree.get(s.colors, seq.len(functions), id)) == 0 { return push(functions, bodies, s, id, cap) }
        return s
    }
    let frame = noun.head(s.frames)
    let id = as_u32(noun.as_field(noun.head(frame)))
    let edges = noun.head(noun.tail(frame))
    let longest = as_u32(noun.as_field(noun.tail(noun.tail(frame))))
    if noun.eq(edges, noun.atom(0)) {
        s.colors = tree.set(s.colors, seq.len(functions), id, noun.atom(2))
        let height = syntax.inc(longest)
        s.heights = tree.set(s.heights, seq.len(functions), id, noun.atom(as_field(height)))
        s.frames = noun.tail(s.frames)
        s.depth = syntax.dec(s.depth)
        return remember(s, height)
    }
    let callee = as_u32(noun.as_field(noun.head(edges)))
    s.frames = noun.pair(noun.pair(noun.atom(as_field(id)), noun.pair(noun.tail(edges), noun.atom(as_field(longest)))), noun.tail(s.frames))
    let color = noun.as_field(tree.get(s.colors, seq.len(functions), callee))
    if color == 1 {
        let declaration = signatures.read(seq.get(functions, callee))
        s.error = syntax.error(5, declaration.name.start, declaration.name.end)
        s.error_function = callee
        return s
    }
    if color == 0 { return push(functions, bodies, s, callee, cap) }
    let height = as_u32(noun.as_field(tree.get(s.heights, seq.len(functions), callee)))
    let mut limit = cap
    if DEPTH_CAP < limit { limit = DEPTH_CAP }
    if limit < as_u32(as_field(s.depth) + as_field(height)) {
        let declaration = signatures.read(seq.get(functions, callee))
        s.error = syntax.error(7, declaration.name.start, declaration.name.end)
        s.error_function = callee
        return s
    }
    remember(s, height)
}

#[pure]
fn chunk(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, input: Walked, cap: U32) -> Walked {
    let mut s = input
    for turn in 0..16 {
        s = step(functions, bodies, roots, s, cap)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Source-built graphs have at most SOURCE_CAP calls and declarations in total.
// Reuse this traversal for all final definitions, then for reachability from main.
#[pure]
#[requires((syntax.SOURCE_CAP < seq.len(functions)) == false)]
pub fn walk(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, cap: U32) -> Walked {
    let zero = syntax.ZERO
    let mut s = Walked { colors: tree.empty(tree.shape(seq.len(functions)).height), heights: tree.empty(tree.shape(seq.len(functions)).height), frames: noun.atom(0),
        depth: zero, next: zero, done: false, error: syntax.error(0, zero, zero), error_function: signatures.NONE }
    for turn in 0..1024 {
        s = chunk(functions, bodies, roots, s, cap)
        if syntax.either(s.done, (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

lib/std/compiler/nox/constant_imports.tr.source_text:
module std.compiler.nox.constant_imports

use vm.nox.noun
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.ascii
use std.compiler.nox.qualified_name
use std.compiler.nox.constant_exports

// An immutable direct-use view. The graph owns cached validated sources/names;
// each dependency publishes its final exports before this view is constructed.
pub struct View {
    pub sources: bytes.BytesTable, pub names: bytes.BytesTable,
    pub exports: constant_exports.Bank, pub uses: Noun
}

#[pure]
pub fn empty() -> View {
    View { sources: bytes.table_empty(), names: bytes.table_empty(),
        exports: constant_exports.empty(syntax.ZERO), uses: noun.atom(0) }
}

#[pure]
fn alias(prefix: bytes.Bytes, owner: bytes.Bytes) -> Bool {
    if noun.eq(bytes.to_noun(prefix), bytes.to_noun(owner)) { return true }
    let mut start = syntax.ZERO
    let mut pos = syntax.ZERO
    for letter in 0..255 {
        if pos == bytes.len(owner) { return ascii.same(owner, start, pos, prefix) }
        if bytes.get(owner, pos) == as_u32(46) { start = syntax.inc(pos) }
        pos = syntax.inc(pos)
    }
    ascii.same(owner, start, pos, prefix)
}

#[pure]
pub fn lookup(source: bytes.Bytes, name: qualified_name.Name, view: View) -> constant_exports.Found {
    let mut found = constant_exports.Found { exists: false, id: syntax.ZERO }
    if bytes.len(name.prefix) == syntax.ZERO { return found }
    let mut rest = view.uses
    for step in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return found }
        // module_store.Use starts with its compact target ID. Lookup retains
        // the complete record while reading only this field from the graph.
        let target = as_u32(noun.as_field(noun.head(noun.head(rest))))
        let owner = bytes.table_get(view.names, target)
        if alias(name.prefix, owner) {
            let candidate = constant_exports.find(view.exports, target,
                bytes.table_get(view.sources, target), source, name.member)
            // Missing/private members of a later same-basename owner leave the
            // earlier public symbol visible. Repeated uses retain source order.
            if candidate.exists { found = candidate }
        }
        rest = noun.tail(rest)
    }
    assert(noun.eq(rest, noun.atom(0)))
    found
}

lib/std/compiler/nox/ascii.tri.source_text:
module std.compiler.nox.ascii

use std.nox.bytes
use std.compiler.nox.syntax
use vm.core.convert
use vm.core.field

#[pure]
pub fn digit(value: U32) -> Bool { syntax.both((value < as_u32(48)) == false, value < as_u32(58)) }

#[pure]
pub fn initial(value: U32) -> Bool {
    if value == as_u32(95) { return true }
    if value < as_u32(65) { return false }
    if value < as_u32(91) { return true }
    if value < as_u32(97) { return false }
    value < as_u32(123)
}

#[pure]
pub fn space(value: U32) -> Bool {
    if value == as_u32(9) { return true }
    if value == as_u32(10) { return true }
    if value == as_u32(12) { return true }
    if value == as_u32(13) { return true }
    value == as_u32(32)
}

#[pure]
#[requires((bytes.len(source) < end) == false)]
#[requires((end < start) == false)]
pub fn same(source: bytes.Bytes, start: U32, end: U32, name: bytes.Bytes) -> Bool {
    let length = as_u32(field.sub(as_field(end), as_field(start)))
    if (length == bytes.len(name)) == false { return false }
    let mut pos = start
    for i in 0..255 {
        if pos == end { return true }
        if (bytes.get(source, pos) == bytes.get(name, i)) == false { return false }
        pos = syntax.inc(pos)
    }
    pos == end
}

// 1 identifier; 10 program; 11 fn; 12 Field; 13 reserved/unsupported.
#[pure]
pub fn keyword(value: Field) -> Field {
    if value == 31651020194079085 { return 10 } // program
    if value == 120325194214501 { return 13 } // module
    if value == 7697253 { return 13 } // use
    if value == 26222 { return 11 } // fn
    if value == 7370082 { return 40 } // pub
    if value == 7562595 { return 13 } // sec
    if value == 7103860 { return 15 } // let
    if value == 7173492 { return 16 } // mut
    if value == 427071271796 { return 45 } // const
    if value == 126943973696372 { return 39 } // struct
    if value == 26982 { return 23 } // if
    if value == 1701606245 { return 24 } // else
    if value == 6713202 { return 31 } // for
    if value == 26990 { return 32 } // in
    if value == 27707097871574372 { return 13 } // bounded
    if value == 125780071117422 { return 25 } // return
    if value == 1953658213 { return 21 } // true
    if value == 439721161573 { return 22 } // false
    if value == 435778055796 { return 13 } // event
    if value == 125780103618924 { return 13 } // reveal
    if value == 1936023916 { return 13 } // seal
    if value == 469786452840 { return 13 } // match
    if value == 302415965284 { return 12 } // Field
    if value == 97059439209572 { return 13 } // XField
    if value == 1114599276 { return 20 } // Bool
    if value == 5583666 { return 28 } // U32
    if value == 1315927406 { return 34 } // Noun
    if value == 75219496956788 { return 35 } // Digest
    if value == 95 { return 13 } // _
    if value == 6386541 { return 13 } // asm
    1
}

#[pure]
pub fn punctuation(value: U32) -> Bool {
    let codes = [35,91,93,59,61,44,46,58,38,94,60,62]
    for i in 0..12 { if as_field(value) == codes[i] { return true } }
    false
}

// Call punctuation belongs to an identifier only on the same physical line.
#[pure]
#[requires((bytes.len(source) < end) == false)]
#[requires((end < start) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn same_line(source: bytes.Bytes, start: U32, end: U32) -> Bool {
    let mut pos = start
    for step in 0..4096 {
        if pos == end { return true }
        if bytes.get(source, pos) == as_u32(10) { return false }
        pos = syntax.inc(pos)
    }
    true
}

lib/std/compiler/nox/lexer.tri.source_text:
module std.compiler.nox.lexer

use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.ascii
use vm.core.convert
use vm.core.field

#[pure]
fn identifier(source: bytes.Bytes, start: U32) -> syntax.Token {
    let mut pos = start
    let mut packed: Field = 0
    for step in 0..4096 {
        if pos == bytes.len(source) { return syntax.token(ascii.keyword(packed), start, pos, packed) }
        let c = bytes.get(source, pos)
        if (syntax.either(ascii.initial(c), ascii.digit(c))) == false {
            return syntax.token(ascii.keyword(packed), start, pos, packed)
        }
        if step < as_u32(7) { packed = packed * 256 + as_field(c) }
        else { packed = 0 }
        pos = syntax.inc(pos)
    }
    syntax.token(1, start, pos, 0)
}

#[pure]
fn decimal(source: bytes.Bytes, start: U32) -> syntax.Token {
    let max_digits = [1,8,4,4,6,7,4,4,0,7,3,7,0,9,5,5,1,6,1,5]
    let mut pos = start
    let mut significant = syntax.ZERO
    let mut comparison: Field = 0
    let mut value: Field = 0
    let mut overflow = false
    for step in 0..4096 {
        if pos == bytes.len(source) {
            if overflow { return syntax.token(14, start, pos, 0) }
            return syntax.token(2, start, pos, value)
        }
        let c = bytes.get(source, pos)
        if ascii.digit(c) == false {
            if overflow { return syntax.token(14, start, pos, 0) }
            return syntax.token(2, start, pos, value)
        }
        let digit = field.sub(as_field(c), 48)
        value = value * 10 + digit
        if syntax.either((significant == syntax.ZERO) == false, (digit == 0) == false) {
            if significant < as_u32(20) {
                let expected = max_digits[significant]
                if comparison == 0 {
                    if as_u32(digit) < as_u32(expected) { comparison = 1 }
                    if as_u32(expected) < as_u32(digit) { comparison = 2 }
                }
            }
            significant = syntax.inc(significant)
            if syntax.either(as_u32(20) < significant, (syntax.both(significant == as_u32(20), comparison == 2))) { overflow = true }
        }
        pos = syntax.inc(pos)
    }
    if overflow { return syntax.token(14, start, pos, 0) }
    syntax.token(2, start, pos, value)
}

// Token kinds: EOF=0, identifier=1, decimal=2, +=3, *=4, (=5, )=6,
// {=7, }=8, ->=9, program=10, fn=11, Field=12, unsupported=13, invalid=14,
// let=15, mut=16, colon=17, assignment=18, equality=19, Bool=20,
// true=21, false=22, if=23, else=24, return=25, comma=26;
// 43 is semicolon; 44 is the internal array marker; const=45; #=46.
// 38 is the internal tuple marker; struct=39, pub=40, .=41, internal record marker=42.
// 27 is the internal call marker; U32=28, less-than=29, &=30, for=31, in=32, ..=33, Noun=34, Digest=35, [=36, ]=37.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((bytes.len(source) < start) == false)]
pub fn next(source: bytes.Bytes, start: U32) -> syntax.Token {
    let mut pos = start
    let mut comment = false
    for step in 0..4097 {
        if pos == bytes.len(source) { return syntax.token(0, pos, pos, 0) }
        let c = bytes.get(source, pos)
        if comment {
            if c == as_u32(10) { comment = false }
        } else if ascii.space(c) == false {
            // Look ahead only for a slash. Eager helper arguments otherwise
            // charge every tuple/group delimiter for comment-prefix work.
            if c == as_u32(47) {
                if syntax.inc(pos) < bytes.len(source) {
                    if bytes.get(source, syntax.inc(pos)) == as_u32(47) { comment = true }
                }
            }
            if comment == false {
                // Parentheses delimit calls, groups and tuples. Recognize them
                // before identifier/decimal classification on the hot path.
                if c == as_u32(40) { return syntax.token(5, pos, syntax.inc(pos), 0) }
                if c == as_u32(41) { return syntax.token(6, pos, syntax.inc(pos), 0) }
                if ascii.initial(c) { return identifier(source, pos) }
                if ascii.digit(c) { return decimal(source, pos) }
                let end = syntax.inc(pos)
                if c == as_u32(43) { return syntax.token(3, pos, end, 0) }
                if c == as_u32(42) { return syntax.token(4, pos, end, 0) }
                if c == as_u32(123) { return syntax.token(7, pos, end, 0) }
                if c == as_u32(125) { return syntax.token(8, pos, end, 0) }
                if syntax.both(c == as_u32(45), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(62) { return syntax.token(9, pos, syntax.inc(end), 0) }
                }
                if syntax.both(c == as_u32(47), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(37) { return syntax.token(13, pos, syntax.inc(end), 0) }
                }
                if c == as_u32(91) { return syntax.token(36, pos, end, 0) }
                if c == as_u32(93) { return syntax.token(37, pos, end, 0) }
                if c == as_u32(59) { return syntax.token(43, pos, end, 0) }
                if c == as_u32(35) { return syntax.token(46, pos, end, 0) }
                if c == as_u32(44) { return syntax.token(26, pos, end, 0) }
                if c == as_u32(60) { return syntax.token(29, pos, end, 0) }
                if c == as_u32(38) { return syntax.token(30, pos, end, 0) }
                if syntax.both(c == as_u32(46), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(46) { return syntax.token(33, pos, syntax.inc(end), 0) }
                }
                if c == as_u32(46) { return syntax.token(41, pos, end, 0) }
                if c == as_u32(58) { return syntax.token(17, pos, end, 0) }
                if c == as_u32(61) {
                    if end < bytes.len(source) {
                        if bytes.get(source, end) == as_u32(61) { return syntax.token(19, pos, syntax.inc(end), 0) }
                    }
                    return syntax.token(18, pos, end, 0)
                }
                // Full-language punctuation outside the current subset.
                if ascii.punctuation(c) {
                    return syntax.token(13, pos, end, 0)
                }
                return syntax.token(14, pos, end, 0)
            }
        }
        pos = syntax.inc(pos)
    }
    syntax.token(14, pos, pos, 0)
}

lib/std/compiler/nox/function_order.tri.source_text:
module std.compiler.nox.function_order

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.signatures

pub struct Ordered { pub ids: seq.Seq, pub next: U32, pub error: syntax.Error }
struct Insert { ids: seq.Seq, gap: U32, done: Bool }

#[pure]
fn before(source: bytes.Bytes, left: syntax.Token, right: syntax.Token) -> Bool {
    let mut a = left.start
    let mut b = right.start
    for turn in 0..4096 {
        if a == left.end { return (b == right.end) == false }
        if b == right.end { return false }
        let x = bytes.get(source, a)
        let y = bytes.get(source, b)
        if x < y { return true }
        if y < x { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    false
}

#[pure]
fn insert_chunk(source: bytes.Bytes, functions: seq.Seq, name: syntax.Token, input: Insert) -> Insert {
    let mut s = input
    for turn in 0..8 {
        if s.gap == syntax.ZERO { s.done = true return s }
        let previous = seq.get(s.ids, syntax.dec(s.gap))
        let declaration = signatures.read(seq.get(functions, as_u32(noun.as_field(previous))))
        if before(source, name, declaration.name) == false { s.done = true return s }
        s.ids = seq.set(s.ids, s.gap, previous)
        s.gap = syntax.dec(s.gap)
    }
    s
}

#[pure]
fn insert(source: bytes.Bytes, functions: seq.Seq, input: seq.Seq, id: U32, cap: U32) -> seq.Seq {
    let declaration = signatures.read(seq.get(functions, id))
    let value = noun.atom(as_field(id))
    let mut s = Insert { ids: seq.push(input, value, cap), gap: seq.len(input), done: false }
    for turn in 0..512 {
        s = insert_chunk(source, functions, declaration.name, s)
        if s.done { return seq.set(s.ids, s.gap, value) }
    }
    // At most SOURCE_CAP final bindings can precede this insertion.
    seq.set(s.ids, s.gap, value)
}

#[pure]
fn chunk(source: bytes.Bytes, functions: seq.Seq, input: Ordered, cap: U32) -> Ordered {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(functions) { return s }
        let declaration = signatures.read(seq.get(functions, s.next))
        if signatures.lookup(source, declaration.name, functions) == s.next {
            if seq.len(s.ids) == cap { s.error = syntax.error(7, declaration.name.start, declaration.name.end) return s }
            s.ids = insert(source, functions, s.ids, s.next, cap)
        }
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < seq.len(functions)) == false)]
pub fn sort(source: bytes.Bytes, functions: seq.Seq, cap: U32) -> Ordered {
    let zero = syntax.ZERO
    let mut s = Ordered { ids: seq.empty(), next: zero, error: syntax.error(0, zero, zero) }
    for turn in 0..512 {
        s = chunk(source, functions, s, cap)
        if syntax.either(s.next == seq.len(functions), (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

