    let options = CompileOptions::default()
        .with_package(target_support::triton_package())
        .unwrap();
    trident::tir::builder::TIRBuilder::new(options.target_config)
        .with_module_types(&refs)
        .build_file(&files[1])
        .unwrap();
}

